2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Fabric;
8	use App\Models\FabricCategory;
9	use Illuminate\Console\Command;
10	use Illuminate\Support\Facades\DB;
11	use Illuminate\Support\Str;
12	use OpenSpout\Reader\XLSX\Reader;
13	
14	/**
15	 * Import dei singoli colori tessuto/pelle (`Fabric`) dal listino CAPITAL
16	 * `tessuti_capital.xlsx`, sotto le rispettive `FabricCategory` (tipologie).
17	 *
18	 * Il file elenca 12 tipologie: 8 mappano sulle tipologie del catalogo, 4 sono
19	 * varianti presenti solo qui (3 trapuntate + grana Da Vinci) e hanno una
20	 * FabricCategory dedicata (senza prodotti associati). Le tipologie
21	 * "Nabuk treccia" e "Luxury & Exclusive" non hanno colori in questo listino.
22	 *
23	 * Nome colore = colonna D (Codice) + colonna E (Colore). Slug = categoria +
24	 * colonna P (CODICE) quando presente, altrimenti derivato dal nome (garantisce
25	 * unicità globale: P non è unico tra soft-grain e Da Vinci, il nome non è unico
26	 * tra sintetica e sintetica TRAP).
27	 *
28	 * Prerequisito: MaterialFabricSeeder (tassonomia FabricCategory). Idempotente.
29	 */
30	class ImportFabrics extends Command
31	{
32	    protected $signature = 'app:import-fabrics '
33	        . '{--file=storage/app/private/import/indoor/tessuti_capital.xlsx} '
34	        . '{--fresh : Svuota le fabrics delle tipologie interessate prima di reimportare}';
35	
36	    protected $description = 'Import dei colori tessuto/pelle (Fabric) dal listino CAPITAL';
37	
38	    /** Indici colonna (0-based) nel listino CAPITAL. */
39	    private const COL = [
40	        'tipologia' => 0,   // A
41	        'codice' => 3,      // D
42	        'colore' => 4,      // E
43	        'sku' => 15,        // P (CODICE)
44	    ];
45	
46	    /**
47	     * Tipologia CAPITAL (chiave normalizzata: lowercase, trim, spazi collassati)
48	     * → slug FabricCategory di destinazione.
49	     *
50	     * @var array<string, string>
51	     */
52	    private const TIPOLOGIA_MAP = [
53	        'bouclè bi-elastico' => 'boucle-fabric',
54	        'ciniglia' => 'lord-fabric',
55	        'tessuto unito' => 'york-fabric',
56	        'velluto unito' => 'velvet',
57	        'velluto trapuntato' => 'velluto-trapuntato',
58	        'pelle sintetica' => 'synthetic-leather',
59	        'pelle sintetica trap' => 'pelle-sintetica-trap',
60	        'pelle camosciata' => 'vintage-leather',
61	        'pelle grana vellutata' => 'soft-grain-leather',
62	        'pelle grana da vinci' => 'pelle-grana-da-vinci',
63	        'pelle nabuk' => 'nabuk-leather',
64	        'pelle nabuk trap.' => 'nabuk-trap',
65	    ];
66	
67	    /** @var array<string, FabricCategory> */
68	    private array $categoryCache = [];
69	
70	    /** @var array<string, int> sort progressivo per categoria */
71	    private array $sortCounter = [];
72	
73	    public function handle(): int
74	    {
75	        $file = (string) $this->option('file');
76	        if (! is_file($file)) {
77	            $this->error("File non trovato: {$file}");
78	
79	            return self::FAILURE;
80	        }
81	
82	        $stats = ['rows' => 0, 'imported' => 0, 'skipped' => 0, 'unmapped' => 0];
83	        $unmapped = [];
84	
85	        DB::transaction(function () use ($file, &$stats, &$unmapped): void {
86	            if ($this->option('fresh')) {
87	                $slugs = array_values(array_unique(array_values(self::TIPOLOGIA_MAP)));
88	                $categoryIds = FabricCategory::query()->whereIn('slug', $slugs)->pluck('id');
89	                Fabric::query()->whereIn('fabric_category_id', $categoryIds)->delete();
90	            }
91	
92	            $header = true;
93	            $reader = new Reader();
94	            $reader->open($file);
95	            foreach ($reader->getSheetIterator() as $sheet) {
96	                foreach ($sheet->getRowIterator() as $row) {
97	                    if ($header) {
98	                        $header = false;
99	
100	                        continue;
101	                    }
102	
103	                    $cells = array_values(array_map(fn ($c): mixed => $c->getValue(), $row->getCells()));
104	                    $tipologia = $this->s($cells[self::COL['tipologia']] ?? '');
105	                    if ($tipologia === '') {
106	                        continue;
107	                    }
108	                    $stats['rows']++;
109	
110	                    $key = $this->normalize($tipologia);
111	                    $slug = self::TIPOLOGIA_MAP[$key] ?? null;
112	                    if ($slug === null) {
113	                        $stats['unmapped']++;
114	                        $unmapped[$tipologia] = true;
115	
116	                        continue;
117	                    }
118	
119	                    $codice = $this->s($cells[self::COL['codice']] ?? '');
120	                    $colore = $this->s($cells[self::COL['colore']] ?? '');
121	                    $name = trim("{$codice} {$colore}");
122	                    if ($name === '') {
123	                        $stats['skipped']++; // riga senza colore (es. Velluto trapuntato)
124	
125	                        continue;
126	                    }
127	
128	                    $sku = $this->s($cells[self::COL['sku']] ?? '');
129	                    $fabricSlug = $slug . '-' . Str::slug($sku !== '' ? $sku : $name);
130	
131	                    $category = $this->resolveCategory($slug);
132	                    Fabric::query()->updateOrCreate(
133	                        ['slug' => $fabricSlug],
134	                        [
135	                            'fabric_category_id' => $category->id,
136	                            'name' => ['it' => $name, 'en' => $name],
137	                            'sort' => $this->sortCounter[$slug] = ($this->sortCounter[$slug] ?? 0) + 1,
138	                        ],
139	                    );
140	                    $stats['imported']++;
141	                }
142	
143	                break;
144	            }
145	            $reader->close();
146	        });
147	
148	        if ($unmapped !== []) {
149	            $this->warn('Tipologie non mappate (ignorate): ' . implode(', ', array_keys($unmapped)));
150	        }
151	
152	        $this->info('Import colori tessuto completato.');
153	        $this->table(
154	            ['Metrica', 'Valore'],
155	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
156	        );
157	
158	        return self::SUCCESS;
159	    }
160	
161	    private function resolveCategory(string $slug): FabricCategory
162	    {
163	        return $this->categoryCache[$slug] ??= FabricCategory::query()->firstOrCreate(
164	            ['slug' => $slug],
165	            ['name' => ['it' => Str::headline($slug), 'en' => Str::headline($slug)]],
166	        );
167	    }
168	
169	    private function normalize(string $value): string
170	    {
171	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
172	    }
173	
174	    private function s(mixed $value): string
175	    {
176	        return is_scalar($value) ? trim((string) $value) : '';
177	    }
178	}
179

